import { describe, it, expect } from "vitest";
import cases from "../../protocol/fixtures/pairing-v3.json";
import { parsePairing } from "../src/client/pairing";

/// The v3 carrier, against the SAME cross-implementation vectors both other suites assert
/// (`protocol/fixtures/pairing-v3.json`, generated by a third implementation). A parser that agrees
/// with itself and with nothing else is the failure this repo has paid for before.
const V = (cases as { cases: Array<{ name: string; encoded: string; code: string; token: string; psk: string }> }).cases;
const first = V[0]!;
const hex = (h: string): Uint8Array => Uint8Array.from(h.match(/../g) ?? [], (b) => parseInt(b, 16));

describe("parsePairing", () => {
  it("derives every cross-implementation vector", async () => {
    for (const c of V) {
      const r = await parsePairing(c.encoded);
      expect(r, c.name).not.toBeNull();
      expect(r!.code, c.name).toBe(c.code);
      expect(r!.token, c.name).toBe(c.token);
      expect([...r!.psk!], c.name).toEqual([...hex(c.psk)]);
    }
  });

  it("produces a lowercase token", async () => {
    const r = await parsePairing(first.encoded);
    expect(r!.token).toBe(r!.token.toLowerCase());
  });

  // **THE SEED TRAVELS IN THE FRAGMENT.** A query string reaches the Control Plane on the first
  // navigation and §9.1 forbids the seed getting there, so a link that carries one puts it after `#`.
  it("reads a seed out of a link's fragment", async () => {
    const r = await parsePairing(`https://host.example/#pair=${first.encoded}`);
    expect(r!.code).toBe(first.code);
    expect(r!.psk).toBeDefined();
  });

  it("prefers the fragment's seed over a weaker code+token in the query", async () => {
    const r = await parsePairing(
      `https://host.example/?code=WRONGcod&token=00000000-0000-4000-8000-000000000000#pair=${first.encoded}`);
    expect(r!.code).toBe(first.code);
    expect(r!.psk).toBeDefined();
  });

  // A `?code=&token=` link admits a client to the room and gives it nothing to handshake `pair`
  // with. That is a real difference, so the absence of a psk is asserted rather than assumed.
  it("extracts code+token from a pasted URL, WITHOUT a psk", async () => {
    const r = await parsePairing(
      "https://host.example/?code=rm5skaUZ&token=d5a9507e-22e8-49e7-8a9d-045c82960c23");
    expect(r).toEqual({ code: "rm5skaUZ", token: "d5a9507e-22e8-49e7-8a9d-045c82960c23" });
    expect(r!.psk).toBeUndefined();
  });

  it("extracts from a bare query string", async () => {
    expect(await parsePairing("?code=abc&token=xyz")).toEqual({ code: "abc", token: "xyz" });
  });

  // A seed in the QUERY is not accepted, and that refusal is the point: reading one there would
  // turn a correct link into a leak the moment someone rewrote it by hand.
  it("refuses a seed offered in the query", async () => {
    expect(await parsePairing(`https://host.example/?pair=${first.encoded}`)).toBeNull();
  });

  it("returns null for a URL missing the token", async () => {
    expect(await parsePairing("https://host/?code=rm5skaUZ")).toBeNull();
  });

  it("returns null for empty, junk, and the RETIRED v2 carrier", async () => {
    expect(await parsePairing("")).toBeNull();
    expect(await parsePairing("   ")).toBeNull();
    expect(await parsePairing("!!! not base64 !!!")).toBeNull();
    // 30 characters, token-first — what v2 looked like. It is not a v3 seed and must not be read as
    // one: the two carriers cannot be confused in either direction, which is what §9.1 asks for.
    expect(await parsePairing("1alQfiLoSeeKnQRcgpYMI65ubJGlGQ")).toBeNull();
  });

  it("trims surrounding whitespace", async () => {
    const r = await parsePairing(`  ${first.encoded}  `);
    expect(r!.code).toBe(first.code);
  });
});
